/* @lc app=leetcode id=1434 lang=kotlin */ class Solution { fun numberWays(hats: List<List<Int>>): Int = hats.size.let { n -> (1..40).fold(LongArray(1 shl n).also { it[0] = 1 }) { dp, h -> dp.copyOf().also { nd -> hats.indices.filter { h in hats[it] }.forEach { p -> (0 until (1 shl n)).filter { m -> m shr p and 1 == 0 }.forEach { m -> nd[m or (1 shl p)] = (nd[m or (1 shl p)] + dp[m]) % 1_000_000_007 } } } }[(1 shl n) - 1].toInt() } }